-- Local test fixture: column names/types verified against live catalog 2026-10-29.
create role anon; create role authenticated; create role service_role bypassrls;
create schema auth;
create table auth.users(id uuid primary key,email text,phone text,email_confirmed_at timestamptz,phone_confirmed_at timestamptz,raw_app_meta_data jsonb default '{}');
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
create function auth.role() returns text language sql stable as $$ select current_setting('request.jwt.claim.role',true) $$;
create table public.stores("seller_id" uuid primary key,"business_name" text,"business_type" text,"tax_number" text,"category" text,"has_physical_store" boolean,"contact_name" text,"email" text,"phone" text,"address" text,"city" text,"district" text,"postal_code" text,"bank_name" text,"iban" text,"account_holder" text,"logo_url" text,"cover_url" text,"gallery_images" text[],"banners" text[],"slogan" text,"description" text,"whatsapp" text,"support_phone" text,"instagram" text,"facebook" text,"twitter" text,"website" text,"working_hours" text,"is_store_open" boolean,"accept_new_orders" boolean,"allow_messaging" boolean,"is_holiday_mode" boolean,"rating" double precision,"is_verified" boolean,"created_at" timestamp with time zone default now(),"updated_at" timestamp with time zone default now(),"store_lat" double precision,"store_lng" double precision,"seller_videos" text[],"is_deletion_requested" boolean,"follower_count" integer,"receipt_branch_label" text,"receipt_footer_note" text,"is_brand_verified" boolean);
create table public.store_tables("id" uuid default gen_random_uuid() primary key,"seller_id" uuid,"table_number" integer,"qr_token" text,"is_active" boolean,"created_at" timestamp with time zone default now(),"updated_at" timestamp with time zone default now(),"area_id" uuid,"area_name" text,"area_table_number" integer,"table_name" text,"display_label" text);
create table public.store_sub_admins("id" uuid default gen_random_uuid() primary key,"store_id" uuid,"email" text,"phone" text,"permissions" text[] default '{}'::text[],"status" text,"created_at" timestamp with time zone default now());
create table public.orders("id" uuid default gen_random_uuid() primary key,"user_id" uuid,"order_number" text,"status" text,"payment_method" text,"payment_card_name" text,"payment_card_last4" text,"delivery_type" text,"delivery_slot" text,"delivery_address" jsonb,"subtotal_amount" numeric,"shipping_amount" numeric,"discount_amount" numeric,"total_amount" numeric,"currency" text,"created_at" timestamp with time zone default now(),"updated_at" timestamp with time zone default now(),"total_delivery_fee" numeric,"customer_delivery_fee" numeric,"seller_delivery_fee" numeric,"wallet_reserve_status" text,"shipment_type" text,"selected_branch_id" uuid,"distance_km" numeric,"branch_distance_km" numeric,"delivery_quote_id" uuid,"restaurant_id" uuid,"table_id" uuid,"waiter_id" uuid,"order_status" text,"order_type" text,"notes" text,"idempotency_key" text,"payment_status" text,"is_test" boolean,"local_order_id" text);
create table public.order_items("id" uuid default gen_random_uuid() primary key,"order_id" uuid,"seller_id" uuid,"product_id" text,"product_code" text,"product_name" text,"store_name" text,"product_image_url" text,"attributes" jsonb not null default '{}'::jsonb,"quantity" integer,"unit_price" numeric,"total_price" numeric,"status" text,"created_at" timestamp with time zone default now(),"updated_at" timestamp with time zone default now(),"cargo_company" text,"tracking_number" text,"shipment_step" text,"station_id" uuid,"item_note" text,"kitchen_status" text,"sent_to_kitchen_at" timestamp with time zone,"line_total" numeric);
create table public.print_jobs("id" uuid default gen_random_uuid() primary key,"restaurant_id" uuid,"order_id" uuid,"station_id" uuid,"printer_id" uuid,"job_type" text,"status" text,"payload" jsonb,"retry_count" integer,"last_error" text,"printed_at" timestamp with time zone,"created_at" timestamp with time zone default now(),"order_saved_at" timestamp with time zone,"print_job_created_at" timestamp with time zone,"hub_job_received_at" timestamp with time zone,"claimed_at" timestamp with time zone,"dispatch_started_at" timestamp with time zone,"printer_write_started_at" timestamp with time zone,"printer_write_completed_at" timestamp with time zone,"completed_at" timestamp with time zone,"document_type" text,"printer_role" text,"claimed_by" text,"last_attempt_at" timestamp with time zone);
create table public.printers("id" uuid default gen_random_uuid() primary key,"restaurant_id" uuid,"name" text,"code" text,"connection_type" text,"ip_address" text,"port" integer,"device_identifier" text,"paper_width_mm" integer,"is_active" boolean,"created_at" timestamp with time zone default now(),"supports_cut" boolean,"charset" text,"assigned_roles" jsonb,"last_test_print_at" timestamp with time zone,"last_error" text,"test_print_status" text,"code_page" integer,"printer_profile_id" text,"receipt_length_preset" text,"receipt_bottom_feed_lines" integer,"receipt_cut_feed_lines" integer,"receipt_min_trailing_blank_lines" integer,"receipt_bottom_padding_px" integer,"receipt_min_receipt_height_px" integer,"print_size" text);
create table public.stations("id" uuid default gen_random_uuid() primary key,"restaurant_id" uuid,"name" text,"code" text,"color" text,"is_active" boolean,"created_at" timestamp with time zone default now());
create table public.station_printers("id" uuid default gen_random_uuid() primary key,"station_id" uuid,"printer_id" uuid,"is_primary" boolean,"created_at" timestamp with time zone default now());
create table public.users("id" uuid default gen_random_uuid() primary key,"email" text,"display_name" text,"photo_url" text,"phone" text,"role" text,"is_seller_approved" boolean,"weight" double precision,"height" double precision,"gender" text,"birth_date" text,"style" text,"address" text,"favorites" jsonb,"created_at" timestamp with time zone default now(),"updated_at" timestamp with time zone default now(),"addresses" jsonb,"savedCards" jsonb,"product_lists" jsonb,"cart" jsonb,"followedStores" jsonb,"is_ihiz_approved" boolean);
create table public.store_branches("id" uuid default gen_random_uuid() primary key,"store_id" uuid,"branch_code" text,"name" text,"city" text,"district" text,"address_text" text,"latitude" double precision,"longitude" double precision,"status" text,"is_primary" boolean,"created_at" timestamp with time zone default now(),"updated_at" timestamp with time zone default now());
create table public.table_orders("id" uuid default gen_random_uuid() primary key,"seller_id" text,"table_number" integer,"items" jsonb,"status" text,"created_at" timestamp with time zone default now(),"revision" integer,"updated_at" timestamp with time zone default now(),"last_edit_summary" jsonb,"last_edit_note" text,"display_table_label" text,"table_display_name" text,"table_name" text,"table_area_name" text,"area_name" text,"area_table_number" integer,"placement_source" text);
create table public.table_order_history("id" uuid default gen_random_uuid() primary key,"original_order_id" uuid,"seller_id" uuid,"table_number" integer,"items" jsonb,"status" text,"revision" integer,"last_edit_summary" jsonb,"last_edit_note" text,"payment_method" text,"payment_note" text,"waiter_id" uuid,"waiter_name" text,"grand_total" numeric,"session_key" text,"opened_at" timestamp with time zone,"closed_at" timestamp with time zone,"created_at" timestamp with time zone default now(),"table_name" text,"display_table_label" text,"table_display_name" text,"table_area_name" text,"archived_at" timestamp with time zone,"archived_orders" jsonb);
create unique index idx_orders_restaurant_local_order on orders(restaurant_id,local_order_id) where local_order_id is not null;
create table restaurant_daily_order_counters(restaurant_id uuid,order_date date,last_no integer,updated_at timestamptz,primary key(restaurant_id,order_date));
create table restaurant_print_station_configs(restaurant_id uuid primary key,print_system_enabled boolean);
-- Mirror the live money-authority INSERT precondition.
create function test_money_guard() returns trigger language plpgsql as $$ begin
  if current_setting('ibul.marketplace_order_rpc',true) is distinct from 'on' then raise exception 'ORDERS_INSERT_RPC_ONLY'; end if;
  return new; end $$;
create trigger test_orders_money_guard before insert on orders for each row execute function test_money_guard();
create trigger test_items_money_guard before insert on order_items for each row execute function test_money_guard();
alter table store_sub_admins enable row level security;
create policy store_sub_admins_owner_all on store_sub_admins for all to authenticated using (store_id=auth.uid()) with check(store_id=auth.uid());
grant usage on schema public,auth to authenticated,anon;
grant select,insert,update,delete on all tables in schema public to authenticated;

alter table print_jobs add constraint print_jobs_status_check check(status in ('pending','claimed','printing','completed','failed','paused_by_operator'));

create table finance_income_records(id uuid primary key default gen_random_uuid(),seller_id uuid,net_amount numeric);
alter table finance_income_records enable row level security;
grant select on finance_income_records to authenticated;
create function finance_get_overview(p_seller_id uuid) returns numeric language sql security definer as $$select sum(net_amount) from finance_income_records where seller_id=p_seller_id$$;
create function close_table_with_history(p_seller_id uuid,p_table_number integer) returns jsonb language plpgsql security definer as $$
BEGIN
  return '{}'::jsonb;
END;
$$;

create publication supabase_realtime;
